# Sample code to test regex matching in file contents
import re

def test_regex_in_file(file_path, regex_pattern):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            if re.search(regex_pattern, content):
                print(f"Match found in {file_path}")
            else:
                print(f"No match in {file_path}")
    except Exception as e:
        print(f"Error reading file {file_path}: {e}")

# Example usage
test_regex_in_file('example.txt', r'hello\s(you|world)')
